def aplicar(h):
    for old, new, n in PARES + PARES2:
        c = h.count(old)
        if c < 1:
            raise SystemExit('PROSA NO ENCONTRADO: ' + old[:90])
        if n and c != n:
            raise SystemExit('PROSA %d EN VEZ DE %d: %s' % (c, n, old[:90]))
        h = h.replace(old, new)
    for pat, rep in SUB:
        h = re.sub(pat, rep, h)
    return h
